	}
	if err := fizeau.ValidatePowerBounds(*minPower, *maxPower); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}

	// Handle subcommands
	args := fs.Args()
	if !runSubcommand && len(args) > 0 {
		switch args[0] {
		case "log":
