			fmt.Printf("swe_bench_verified:    %.1f\n", e.SWEBenchVerified)
		}
		if e.SpeedTokensPerSec > 0 {
			fmt.Printf("speed_tokens_per_sec:  %.1f\n", e.SpeedTokensPerSec)
		}
